import { spawn } from 'node:child_process';

const child = spawn('/harness-state/.bun/bin/gbrain', ['serve', '--surface', 'starter', '--advertise', 'verbs'], {
  env: { ...process.env, GBRAIN_HOME: '/harness-state' },
  stdio: ['pipe', 'pipe', 'pipe'],
});

let buf = '';
const pending = new Map();
let nextId = 1;

child.stdout.on('data', (d) => {
  buf += d.toString();
  let idx;
  while ((idx = buf.indexOf('\n')) >= 0) {
    const line = buf.slice(0, idx).trim();
    buf = buf.slice(idx + 1);
    if (!line) continue;
    let msg;
    try { msg = JSON.parse(line); } catch { continue; }
    if (msg.id && pending.has(msg.id)) {
      pending.get(msg.id)(msg);
      pending.delete(msg.id);
    }
  }
});
child.stderr.on('data', (d) => process.stderr.write('[serve] ' + d));

function rpc(method, params) {
  const id = nextId++;
  const p = new Promise((resolve, reject) => {
    pending.set(id, resolve);
    setTimeout(() => reject(new Error('timeout ' + method)), 45000);
  });
  child.stdin.write(JSON.stringify({ jsonrpc: '2.0', id, method, params }) + '\n');
  return p;
}

const init = await rpc('initialize', {
  protocolVersion: '2025-06-18',
  capabilities: {},
  clientInfo: { name: 'openclaw-smoke', version: '1.0.0' },
});
console.log('initialize:', JSON.stringify(init.result?.serverInfo ?? init.error));
child.stdin.write(JSON.stringify({ jsonrpc: '2.0', method: 'notifications/initialized', params: {} }) + '\n');

const tools = await rpc('tools/list', {});
const names = (tools.result?.tools ?? []).map((t) => t.name);
console.log('tools:', names.join(', '));

const recall = await rpc('tools/call', { name: 'recall', arguments: { entity: 'gbrain-install' } });
const text = JSON.stringify(recall.result ?? recall.error);
console.log('recall:', text.slice(0, 700));

child.kill();

